    "# --- Interactive PyVista Visualization with True EDL Shading ---\n",
    "try:\n",
    "    import pyvista as pv\n",
    "    pyvista_available = True\n",
    "except ImportError:\n",
    "    pyvista_available = False\n",
    "    print(\"⚠️ PyVista not installed. Install with: pip install pyvista\")\n",
    "\n",
    "if pyvista_available:\n",
    "    print(\"Creating interactive PyVista visualization with Eye Dome Lighting...\")\n",
    "    \n",
    "    # Load a specific z_norm file (can change to znorm_csf if processed)\n",
    "    las_file = Path('/data/calperumResearch/site1_1_DD0001/lidar/clipped/raster/z_norm/csf/z_norm_csf_tiles_multispectral.106.las')\n",
    "    \n",
    "    if las_file.exists():\n",
    "        las_viz = laspy.read(las_file)\n",
    "        z_norm_viz = np.asarray(las_viz.Z_norm, dtype=np.float32)\n",
    "        \n",
    "        print(f\"Loaded: {las_file.name}\")\n",
    "        print(f\"Points: {len(las_viz.points):,}\")\n",
    "        print(f\"HAG range: {z_norm_viz.min():.3f} - {z_norm_viz.max():.3f} m\")\n",
    "        \n",
    "        # Downsample for better performance\n",
    "        max_pts_pv = 200000\n",
    "        n = len(las_viz.x)\n",
    "        if n > max_pts_pv:\n",
    "            idx = np.random.choice(n, size=max_pts_pv, replace=False)\n",
    "            x_pv = las_viz.x[idx]\n",
    "            y_pv = las_viz.y[idx]\n",
    "            z_pv = las_viz.z[idx]\n",
    "            hag_pv = z_norm_viz[idx]\n",
    "        else:\n",
    "            x_pv = las_viz.x\n",
    "            y_pv = las_viz.y\n",
    "            z_pv = las_viz.z\n",
    "            hag_pv = z_norm_viz\n",
    "        \n",
    "        # Center the point cloud\n",
    "        x_center = (x_pv.max() + x_pv.min()) / 2\n",
    "        y_center = (y_pv.max() + y_pv.min()) / 2\n",
    "        z_center = (z_pv.max() + z_pv.min()) / 2\n",
    "        \n",
    "        x_pv_centered = x_pv - x_center\n",
    "        y_pv_centered = y_pv - y_center\n",
    "        z_pv_centered = z_pv - z_center\n",
    "        \n",
    "        # Create PyVista point cloud with centered coordinates\n",
    "        points = np.column_stack([x_pv_centered, y_pv_centered, z_pv_centered])\n",
