    "# --- Standalone Z_norm Visualization (Matplotlib) ---\n",
    "# Visualize any z_norm file directly\n",
    "import laspy\n",
    "import numpy as np\n",
    "import matplotlib.pyplot as plt\n",
    "from pathlib import Path\n",
    "from mpl_toolkits.mplot3d import Axes3D\n",
    "from matplotlib.colors import LinearSegmentedColormap\n",
    "\n",
    "# Load the file (can change to any z_norm file)\n",
    "las_file = Path('/data/calperumResearch/site1_1_DD0001/lidar/clipped/raster/z_norm/csf/z_norm_csf_tiles_multispectral.106.las')\n",
    "\n",
    "if las_file.exists():\n",
    "    las = laspy.read(las_file)\n",
    "    z_norm = np.asarray(las.Z_norm, dtype=np.float32)\n",
    "    \n",
    "    print(f\"Loaded {len(las.points):,} points from {las_file.name}\")\n",
    "    print(f\"Z_norm range: {z_norm.min():.3f} - {z_norm.max():.3f} m\")\n",
    "    print(f\"Elevation range: {las.z.min():.3f} - {las.z.max():.3f} m\")\n",
    "    \n",
    "    # Downsample for visualization\n",
    "    max_pts = 50000\n",
    "    idx = np.random.choice(len(las.x), size=min(max_pts, len(las.x)), replace=False)\n",
    "    x = las.x[idx]\n",
    "    y = las.y[idx]\n",
    "    z = las.z[idx]\n",
    "    hag = z_norm[idx]\n",
    "    \n",
    "    # Create custom colormap: blue -> green -> yellow -> red (matching CloudCompare)\n",
    "    colors_bgyr = ['blue', 'green', 'yellow', 'red']\n",
    "    cmap_bgyr = LinearSegmentedColormap.from_list('bgyr', colors_bgyr, N=256)\n",
    "    \n",
    "    # Create visualization\n",
    "    fig = plt.figure(figsize=(20, 10))\n",
    "    \n",
    "    # 3D Isometric view (like CloudCompare)\n",
    "    ax1 = fig.add_subplot(1, 2, 1, projection='3d')\n",
    "    sc = ax1.scatter(x, y, z, s=2, c=hag, cmap=cmap_bgyr, alpha=0.8, vmin=0, vmax=4.5)\n",
    "    ax1.set_title(f'Z_norm (HAG) - Isometric View\\n{las_file.name}', fontsize=14, pad=20)\n",
    "    ax1.set_xlabel('X (m)', fontsize=10)\n",
    "    ax1.set_ylabel('Y (m)', fontsize=10)\n",
    "    ax1.set_zlabel('Z elevation (m)', fontsize=10)\n",
    "    ax1.view_init(elev=30, azim=45)\n",
    "    plt.colorbar(sc, ax=ax1, label='Z_norm (HAG in meters)', shrink=0.7, pad=0.1)\n",
    "    \n",
    "    # Top view\n",
    "    ax2 = fig.add_subplot(1, 2, 2)\n",
